"""Locate and wrap a fastText training engine (assumption A14).

Preference order, recorded in `provenance`:
  1. an already importable `fasttext` module (the official Python binding of the
     authors' C++ trainer),
  2. `pip install fasttext-wheel` (prebuilt binary of the same fastText 0.9.2 C++ code),
  3. native build of the cloned authors' repo (`pip install .` / `make`),
  4. fallback: the authors' PyTorch EmbeddingBag fastText model
     (python/doc/examples/FastTextEmbeddingBag.py) -- a re-implementation, which
     downgrades the verdict to partially_reproduced.

All hyperparameters are forwarded verbatim; no author code is rewritten.
"""
import os
import subprocess
import sys
import time


class Engine(object):
    def __init__(self, kind, mod=None):
        self.kind = kind          # 'fasttext-wheel' | 'fasttext (import)' | 'native build' | 'embeddingbag-fallback'
        self.mod = mod
        self.is_reimplementation = kind == "embeddingbag-fallback"

    # --- uniform API ---------------------------------------------------------
    def train(self, input_path, output_prefix, **kwargs):
        if self.is_reimplementation:
            return _EmbeddingBagModel.train(input_path, output_prefix, **kwargs)
        return self.mod.train_supervised(input=input_path, output=output_prefix, **kwargs)

    def test(self, model, test_path):
        """Return (N, P@1, R@1) exactly like `./fasttext test`."""
        if self.is_reimplementation:
            return model.test(test_path)
        return model.test(test_path, k=1)


def _try_import():
    try:
        import fasttext  # noqa
        return fasttext
    except Exception:
        return None


def _try_pip(package):
    try:
        subprocess.check_call([sys.executable, "-m", "pip", "install", "--quiet", package],
                              stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except Exception as e:  # noqa
        print("[engine] pip install %s failed: %s" % (package, e))
        return None
    return _try_import()


def _try_native_build(repo_dir):
    """`pip install .` of the authors' repo (needs a working C++ toolchain)."""
    if not os.path.isdir(repo_dir):
        return None
    try:
        subprocess.check_call([sys.executable, "-m", "pip", "install", "--quiet", repo_dir],
                              stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except Exception as e:  # noqa
        print("[engine] native build failed: %s" % e)
        return None
    return _try_import()


def get_engine(repo_dir=None, allow_install=True):
    mod = _try_import()
    if mod is not None:
        return Engine("fasttext (already importable)", mod)
    if allow_install:
        mod = _try_pip("fasttext-wheel")
        if mod is not None:
            return Engine("fasttext-wheel", mod)
        if repo_dir:
            mod = _try_native_build(repo_dir)
            if mod is not None:
                return Engine("native build of authors' repo", mod)
    # documented last resort: the authors' own PyTorch example re-implementation
    return Engine("embeddingbag-fallback")


# ---------------------------------------------------------------------------
# Fallback: the authors' python/doc/examples/FastTextEmbeddingBag.py model,
# re-implemented with torch.  Only used if no C++ engine can be obtained.
# ---------------------------------------------------------------------------
class _EmbeddingBagModel(object):
    def __init__(self, model, labels, dim, bucket):
        self.model = model
        self.labels = labels
        self.dim = dim
        self.bucket = bucket

    @staticmethod
    def _hash_bigrams(tokens, vocab, bucket):
        feats = [hash(t) % bucket + 1 for t in tokens]
        for a, b in zip(tokens[:-1], tokens[1:]):
            feats.append((hash(a + " " + b) & 0x7FFFFFFF) % bucket + 1)
        return feats

    @classmethod
    def train(cls, input_path, output_prefix, dim=10, lr=0.1, epoch=5, wordNgrams=2,
              bucket=10_000_000, thread=1, verbose=0, seed=0, **kw):
        import torch
        from torch import nn
        torch.manual_seed(seed)
        docs, labels = [], []
        lab_set = set()
        with open(input_path, encoding="utf-8") as f:
            for line in f:
                parts = line.rstrip("\n").split(" ")
                labs = [p for p in parts if p.startswith("__label__")]
                toks = [p for p in parts if p and not p.startswith("__label__")]
                if not labs:
                    continue
                lab_set.add(labs[0])
                docs.append(toks)
                labels.append(labs[0])
        labels = sorted(lab_set)
        l2i = {l: i for i, l in enumerate(labels)}
        n = len(labels)
        emb = nn.EmbeddingBag(bucket + 1, dim, mode="mean", sparse=False)
        lin = nn.Linear(dim, len(labels))
        nn.init.uniform_(emb.weight, -1.0 / dim, 1.0 / dim)
        net = nn.Sequential(emb, lin) if False else None  # keep refs separate
        opt = torch.optim.SGD([{"params": emb.parameters()}, {"params": lin.parameters()}],
                             lr=lr)
        X = [cls._hash_bigrams(d, None, bucket) for d in docs]
        Y = torch.tensor([l2i[l] for l in labels])
        g = torch.Generator().manual_seed(seed)
        bs = 64
        net.train()
        for ep in range(epoch):
            perm = torch.randperm(n, generator=g)
            tot = 0
            for s in range(0, n, bs):
                idx = perm[s:s + bs]
                offs = torch.cumsum(torch.tensor([0] + [len(X[i]) for i in idx[:-1]]), 0)
                flat = torch.tensor([f for i in idx for f in X[i]])
                opt.zero_grad()
                h = emb(flat, torch.tensor(offs.tolist(), dtype=torch.long))
                out = lin(h)
                loss = torch.nn.functional.cross_entropy(out, Y[idx])
                loss.backward()
                # linear lr decay to zero over the run (paper Sec 2 / A6)

