def train(self, input_path, output_prefix, **kwargs):
    """Same flags as `./fasttext supervised -input ... -output ...`.

    The Python binding has no -output argument, so the model is saved to
    <output_prefix>.bin right after training, exactly as the CLI does.
    """
    if self.is_reimplementation:
        return _EmbeddingBagModel.train(input_path, output_prefix, **kwargs)
    kwargs.pop("output", None)
    model = self.mod.train_supervised(input=input_path, **kwargs)
    if output_prefix:
        try:
            model.save_model(output_prefix + ".bin")
        except Exception as e:  # noqa
            print("[engine] warning: could not save model: %s" % e)
    return model

