    with open(contract, encoding="utf-8") as f:
        d = json.load(f)
    for c in d["claims"]:
        if c["id"] == claim_id:
            return float(c["value"])
    raise KeyError(claim_id)


def contract_tolerance():
    contract = os.path.join(config.ROOT, "state", "claim_contract.json")
    with open(contract, encoding="utf-8") as f:
        d = json.load(f)
    return float(d.get("tolerance", {}).get("value", config.TOLERANCE))

